// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(address actor, uint96 value) public {
        vm.assume(actor != address(0));
        MyLog log = new MyLog();

        // initialize C: fix log address, then freeze config
        c.SetLogFile(address(log));
        c.Initialized();

        // any actor with any value (including 0) performs a Put
        vm.deal(actor, uint256(value));
        vm.prank(actor);
        c.Put{value: value}(0);

        // Reference: every successful Put notifies the configured LogFile.
        // Mutant: LogFile stays zero, so the log is never notified.
        assertTrue(log.recorded());
    }
}

contract MyLog {
    bool public recorded;
    function AddMessage(address, uint, string calldata) external { recorded = true; }
}
